public str getName()
{
    return fieldPName(MCRInventTable, DefaultDropShipmentWarehouse);
}

public Set getAllowedValues()
{   
    InventLocation  inventLocation;

    var ret = new Set(Types::String);

    while select InventLocationId from inventLocation 
    {
        if (!ret.in(inventLocation.InventLocationId))
        {   
            ret.add(inventLocation.InventLocationId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(MCRInventTable, DefaultDropShipmentWarehouse));
    qbr.value(queryValue(_value));
}
